contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(data.length >= 0);
        uint balCBefore = address(c).balance;
        uint balThisBefore = address(this).balance;
        bool reverted;
        bytes memory d = data;
        // top-level state-changing call
        c.forward(address(this), d); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && address(c).balance == balCBefore && address(this).balance == balThisBefore);
    }
    receive() external payable {}
    fallback() external payable {}
}

