// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Proxy c;

    function setUp() public {
        c = new Proxy();
    }

    function _run(bytes memory data) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(data.length >= 0);
        uint balCBefore = address(c).balance;
        uint balThisBefore = address(this).balance;
        bool reverted;
        bytes memory d = data;
        try c.forward(address(this), d) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && address(c).balance == balCBefore && address(this).balance == balThisBefore);
    }

    function testFuzz_run(bytes memory data) public {
        _run(data);
    }

    receive() external payable {}

    fallback() external payable {}
}
